const E=window.ATLAS_DATA,C=new Map(E.countries.map(c=>[c.id,c]));let page=0;
function e(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const countries=[...E.countries].sort((a,b)=>a.name.localeCompare(b.name,'ko'));
document.querySelector('#country').innerHTML='<option value="">All countries / 모든 국가</option>'+countries.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('');
document.querySelector('#country').value=new URLSearchParams(location.search).get('country')||'';
function renderEvidence(){const kind=document.querySelector('#kind').value,country=document.querySelector('#country').value,q=document.querySelector('#query').value.toLowerCase(),en=atlasLanguage==='en';document.querySelectorAll('[data-en]').forEach(n=>{n.setAttribute('data-no-translate','');n.textContent=n.dataset[en?'en':'ko'];});const list=kind==='activities'?E.activities.filter(x=>(!country||x.countries.some(z=>z.code===C.get(country)?.iso2))&&JSON.stringify([x.title,x.id]).toLowerCase().includes(q)):E.chemistryRegistry.filter(x=>x.partner_type!=='Bilateral'&&(!country||x.recipient_iso3===country)&&JSON.stringify([x.donor,x.recipient]).toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(list.length/20)-1));document.querySelector('#total').textContent=`${list.length} records`;document.querySelector('#page').textContent=`${page+1} / ${Math.max(1,Math.ceil(list.length/20))}`;document.querySelector('#prev').disabled=page===0;document.querySelector('#next').disabled=(page+1)*20>=list.length;document.querySelector('#evidence-list').setAttribute('data-no-translate','');document.querySelector('#evidence-list').innerHTML=list.slice(page*20,page*20+20).map(x=>kind==='activities'?`<details><summary>${e(x.title)}</summary><p>ID: ${e(x.id)}<br>UNICEF · ${x.countries.map(z=>{const c=E.countries.find(c=>c.iso2===z.code);return e(c?(en?c.english:c.name):z.code);}).join(', ')}<br>${en?'Results / Actual elements':'결과 / 실적 요소'}: ${x.result_count} / ${x.actual_count}<br>${en?'Sector codes':'분야 코드'}: ${x.sectors.map(s=>e(s.code)).join(', ')}</p>${observationHTML(x.id,en)}<p><a href="${e(x.url)}" target="_blank" rel="noopener">${en?'Original source':'원문 출처'} ↗</a></p></details>`:`<details><summary>${e(x.donor)} → ${e(en?C.get(x.recipient_iso3)?.english||x.recipient:C.get(x.recipient_iso3)?.name||x.recipient)}</summary><p>${en?'Historical reference':'과거 참고'} · ${x.source_year} · ${x.chemistry.toFixed(2)} / 100<br>100 × (O + R + D)/3<br>O=${x.components.ownership} / R=${x.components.results_alignment} / D=${x.components.government_data}<br>${en?'Source sheet / row':'원본 시트 / 행'}: ${e(x.source_sheet)} / ${x.source_row}</p></details>`).join('');applyLanguage();}
['kind','country','query'].forEach(id=>document.querySelector('#'+id).addEventListener('input',()=>{page=0;renderEvidence();}));document.querySelector('#prev').onclick=()=>{page--;renderEvidence();};document.querySelector('#next').onclick=()=>{page++;renderEvidence();};document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(renderEvidence)));renderEvidence();

function observationHTML(id,en){return (E.observations||[]).filter(o=>o.activity===id).map(o=>`<details class="observation"><summary>${e(o.title)}</summary><p>${e(o.period.join(' → '))}<br>${en?'Baseline':'기초선'}: ${e(o.baseline?.attributes?.value||'—')}<br>${en?'Target':'목표'}: ${o.targets.map(t=>e(t.attributes.value||'—')).join(' / ')}<br>${en?'Actual':'실적'}: ${o.actuals.map(t=>e(t.attributes.value||'—')).join(' / ')}<br>${en?'Independent verification established':'독립 검증 확인'}: ${o.quality.independent_verification_established?'Yes':'No'}</p></details>`).join('');}
